function longestPalindrome(s: string): string {
  // Границы лучшего найденного палиндрома: s.slice(bestStart, bestEnd)
  let bestStart = 0;
  let bestEnd = 1;

  // Расширяем палиндром от центра (left, right), пока символы совпадают.
  // Возвращаем длину самого длинного палиндрома с этим центром.
  const expand = (left: number, right: number): number => {
    while (left >= 0 && right < s.length && s[left] === s[right]) {
      left--;
      right++;
    }
    // После цикла left и right на шаг вышли за границы палиндрома
    return right - left - 1;
  };

  for (let i = 0; i < s.length; i++) {
    // Нечётная длина: центр — символ i ("aba")
    const odd = expand(i, i);
    // Чётная длина: центр между i и i + 1 ("abba")
    const even = expand(i, i + 1);
    const len = Math.max(odd, even);

    if (len > bestEnd - bestStart) {
      // Восстанавливаем начало по центру i и длине len
      bestStart = i - Math.floor((len - 1) / 2);
      bestEnd = bestStart + len;
    }
  }

  return s.slice(bestStart, bestEnd);
}

// Время: O(n²) — 2n - 1 центров, каждое расширение до O(n)
// Память: O(1)
